#include <bits/stdc++.h>
using namespace std;

vector<string> g, rg;
int n;

vector<string> rotate(const vector<string>& g) {
    vector<string> res(g.size(), string(g.size(), 'O'));
    for (int i = 0; i < (int)g.size(); ++i)
        for (int j = 0; j < (int)g[i].size(); ++j)
            res[g[i].size() - 1 - j][i] = g[i][j];
    return res;
}

vector<string> flipH(const vector<string>& g) {
    vector<string> res(g.size(), string(g.size(), 'O'));
    for (int i = 0; i < (int)g.size(); ++i)
        for (int j = 0; j < (int)g[i].size(); ++j)
            res[g.size() - 1 - i][j] = g[i][j];
    return res;
}

vector<string> flipV(const vector<string>& g) {
    vector<string> res(g.size(), string(g.size(), 'O'));
    for (int i = 0; i < (int)g.size(); ++i)
        for (int j = 0; j < (int)g[i].size(); ++j)
            res[i][g[i].size() - 1 - j] = g[i][j];
    return res;
}

bool check(const vector<string>& a, const vector<string>& b) {
    return a == b;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

#ifndef ONLINE_JUDGE
    freopen("test.txt", "r", stdin);
#endif

    cin >> n;
    g.resize(n);
    rg.resize(n);

    for (int i = 0; i < n; ++i)
        cin >> g[i];
    for (int i = 0; i < n; ++i)
        cin >> rg[i];

    for (int it = 0; it < 4; ++it) {
        if (check(rg, g) || check(flipH(rg), g) || check(flipV(rg), g)) {
            cout << "Yes\n";
            return 0;
        }
        rg = rotate(rg);
    }

    cout << "No\n";
    return 0;
}

